import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **Each session's branch and line counts, and the computer's CPU, memory and
/// disk, against the daemon's own bytes** (minor 31).
///
/// `minor-31-wire.json` is what ccd emits (`fixtures/claude/`, regenerated by
/// ccd's tests and copied here byte for byte); `minor-23-wire.json` and
/// `minor-28-wire.json` are what older daemons emitted.
final class Minor31WireTests: XCTestCase {

    private func wire(_ minor: Int) throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-\(minor)-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ minor: Int, _ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire(minor)[key], "no \(key) in minor-\(minor)-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private func sessions(_ minor: Int) throws -> [SessionSummary] {
        guard case .sessions(let list) = try frame(minor, "sessions") else {
            XCTFail("minor-\(minor) sessions is not a sessions frame")
            return []
        }
        return list
    }

    private func capabilities(_ minor: Int) throws -> Capabilities {
        let advertised = try XCTUnwrap(try wire(minor)["hello_ack_capabilities"])
        return try JSONDecoder().decode(Capabilities.self, from: Data(advertised.canonicalJSONString.utf8))
    }

    func testASummaryCarriesItsBranchAndLineCountsWhenTheDaemonSendsThem() throws {
        let list = try sessions(31)
        XCTAssertEqual(list.count, 2)
        XCTAssertEqual(list[0].gitBranch, "feature/fleet")
        XCTAssertEqual(list[0].diffStat, DiffStat(added: 120, removed: 7))
        XCTAssertNil(list[1].gitBranch)
        XCTAssertNil(list[1].diffStat)
    }

    func testAnOlderDaemonsSummaryHasNoBranchOrLineCounts() throws {
        let list = try sessions(23)
        XCTAssertFalse(list.isEmpty)
        for summary in list {
            XCTAssertNil(summary.gitBranch)
            XCTAssertNil(summary.diffStat)
        }
    }

    func testASummaryKeepsBothFieldsThroughItsOwnEncoding() throws {
        let summary = try sessions(31)[0]
        let again = try JSONDecoder().decode(SessionSummary.self, from: JSONEncoder().encode(summary))
        XCTAssertEqual(again.gitBranch, "feature/fleet")
        XCTAssertEqual(again.diffStat, DiffStat(added: 120, removed: 7))
    }

    func testMachineStatsAreOfferedOnlyWhereAdvertised() throws {
        XCTAssertTrue(try capabilities(31).reportsMachineStats)
        XCTAssertFalse(try capabilities(28).reportsMachineStats)
    }

    func testTheStatsRequestEncodesAsTheDaemonReadsIt() throws {
        let encoded = try JSONDecoder().decode(
            JSONValue.self, from: JSONEncoder().encode(ClientMessage.getMachineStats))
        XCTAssertEqual(encoded, try wire(31)["get_machine_stats_request"])
    }

    func testAWholeSampleDecodesEveryValue() throws {
        guard case .machineStats(let stats) = try frame(31, "machine_stats") else {
            return XCTFail("machine_stats is not a machine_stats frame")
        }
        XCTAssertEqual(stats.cpu, 0.38)
        XCTAssertEqual(stats.memoryUsed, 76_235_669_504)
        XCTAssertEqual(stats.memoryTotal, 206_158_430_208)
        XCTAssertEqual(stats.diskUsed, 1_400_000_000_000)
        XCTAssertEqual(stats.diskTotal, 4_000_000_000_000)
        XCTAssertNotNil(stats.capturedDate)
    }

    func testAValueTheComputerCouldNotReadIsNil() throws {
        guard case .machineStats(let stats) = try frame(31, "machine_stats_partial") else {
            return XCTFail("machine_stats_partial is not a machine_stats frame")
        }
        XCTAssertEqual(stats.cpu, 0.38)
        XCTAssertEqual(stats.memoryTotal, 206_158_430_208)
        XCTAssertNil(stats.diskUsed)
        XCTAssertNil(stats.diskTotal)
    }
}
